    const filteredProducts = useMemo(() => {

        const search =
            searchTerm
                .toLowerCase()
                .trim()


        return products.filter((product) => {

            const productName =
                (product.name || '')
                    .toLowerCase()

            const description =
                (product.description || '')
                    .toLowerCase()

            const productCategory =
                (product.category || '')
                    .toLowerCase()


            // SEARCH MATCH
            const matchesSearch =
                !search ||
                productName.includes(search) ||
                description.includes(search) ||
                productCategory.includes(search)


            // CATEGORY MATCH
            const matchesCategory =
                !category ||
                category === 'Popular' ||
                getCategory(product) === category


            return (
                matchesSearch &&
                matchesCategory
            )

        })

    }, [products, searchTerm, category])


